/// </remarks>
public interface ISATextChunk : global::VeraPdf.Model.SALayer.ISAChunk
{
    /// <summary>
    /// These are measured/derived features of a chunk, not PDF dictionary entries.
    /// C# PORT: Preserve the producer&apos;s units and contrast calculation; a font&apos;s
    /// point size or a platform color type is not automatically an equivalent value.
    /// text size
    /// </summary>
    /// <remarks>DSL Decimal; may be absent or invalid. Java getter: gettextSize.</remarks>
    double? GettextSize();
    /// <summary>
    /// contrast ratio
    /// </summary>
    /// <remarks>DSL Decimal; may be absent or invalid. Java getter: getcontrastRatio.</remarks>
    double? GetcontrastRatio();
    /// <summary>
    /// text weight
    /// </summary>
    /// <remarks>DSL Decimal; may be absent or invalid. Java getter: gettextWeight.</remarks>
    double? GettextWeight();
    /// <summary>
    /// true, if this text chunk has style different from common style
    /// </summary>
    /// <remarks>DSL Boolean; may be absent or invalid. Java getter: gethasSpecialStyle.</remarks>
    bool? GethasSpecialStyle();
    /// <summary>
    /// true, if this text chunk has background different from common background
    /// </summary>
    /// <remarks>DSL Boolean; may be absent or invalid. Java getter: gethasSpecialBackground.</remarks>
    bool? GethasSpecialBackground();
    /// <summary>
    /// true, if this text chunk is underlined
    /// </summary>
    /// <remarks>DSL Boolean; may be absent or invalid. Java getter: getisUnderlined.</remarks>
    bool? GetisUnderlined();
    /// <summary>
    /// ampersand separated list of all parent elements standard types of this text chunk in the structure hierarchy
    /// </summary>
    /// <remarks>DSL String; may be absent or invalid. Java getter: getparentsStandardTypes.</remarks>
    string? GetparentsStandardTypes();
    /// <summary>
    /// true, if this text chunk consists of white spaces
    /// </summary>
    /// <remarks>DSL Boolean; may be absent or invalid. Java getter: getisWhiteSpaceChunk.</remarks>
    bool? GetisWhiteSpaceChunk();
}

